window.AUTH=window.AUTH||{};window.AUTH["06-84"]={"d":"06-84","id":"2006/06-84","n":"Safeco Insurance Co. of America v. Burr","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae in support of vacatur in","date":"","url":"https://www.justice.gov/osg/media/212921/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/06-100-safeco-ins-co-am-v-burr-geico-gen-ins-co-v-edo-amicus-merits","n":110}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep551/usrep551047/usrep551047.pdf","tr":true,"items":[{"t":"case","label":"A.J. McNulty & Co. v. Secretary of Labor","cite":"283 F.3d 328","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/283/328/","by":{"0":"11"}},{"t":"case","label":"Armenta v. City of Casa Grande","cite":"71 P.3d 359","y":2003,"court":"Ariz. Ct. App.","url":"https://www.courtlistener.com/c/P.3d/71/359/","by":{"0":"18"}},{"t":"case","label":"Asbury v. Brougham","cite":"866 F.2d 1276","y":1989,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/866/1276/","by":{"0":"19"}},{"t":"case","label":"Barbour v. Merrill","cite":"48 F.3d 1270","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/48/1270/","by":{"0":"19"}},{"t":"case","label":"Barry v. Edmunds","cite":"116 U.S. 550","y":1886,"id":"scdb/1885-129","sc":1,"sum":"A suit cannot properly be dismissed by a Circuit Court of the United States as not substantially involving a controversy within the jurisdiction oí the court, unless the facts when tnado to appear on the record) create a.legal certainty of that conclusion.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Baystate Alternative Staffing, Inc. v. Herman","cite":"163 F.3d 668","y":1998,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/163/668/","by":{"0":"10"}},{"t":"case","label":"Bevolo v. Carter","cite":"447 F.3d 979","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/447/979/","by":{"0":"19"}},{"t":"case","label":"Brock v. Morello Bros. Constr., Inc.","cite":"809 F.2d 161","y":1987,"url":"https://www.courtlistener.com/c/F.2d/809/161/","by":{"0":"11, 22"}},{"t":"case","label":"Bryan v. United States","cite":"317 U.S. 184","y":1998,"id":"1997/96-8422","sc":1,"op":4,"sum":"The Court held that the term \"willfully\" in section 924(a)(1)(D) requires proof only that the defendant knew his conduct was unlawful, not that he also knew of the federal licensing requirement.","sumSrc":"Oyez","by":{"0":"8, 9, 15"}},{"t":"case","label":"Casella v. Equifax Credit Info. Servs.","cite":"56 F.3d 469","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/56/469/","by":{"0":"19"}},{"t":"case","label":"Cooper v. Rosston","cite":"756 P.2d 1125","y":1988,"court":"Mont.","url":"https://www.courtlistener.com/c/P.2d/756/1125/","by":{"0":"18"}},{"t":"case","label":"Cornist v. B.J.T. Auto Sales, Inc.","cite":"272 F.3d 322","y":2001,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/272/322/","by":{"0":"26"}},{"t":"case","label":"Cushman v. Trans Union Corp.","cite":"115 F.3d 220","y":1997,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/115/220/","op":1,"by":{"0":"6, 19"}},{"t":"case","label":"Dixon v. United States","cite":"126 S. Ct. 2437","y":2006,"id":"2005/05-7053","sc":1,"ar":1,"sum":"In a 7-to-2 decision authored by Justice John Paul Stevens, the Supreme Court held that the government meets its evidentiary burden when it proves beyond a reasonable doubt that the defendant acted \"knowingly\" and \"willfully.\" Dixon had argued that duress would make it impossible for a defendant to act \"willfully\" (and that the government therefore had to prove she did not act under duress in order to prove she acted willfully).","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Doe v. Chao","cite":"540 U.S. 614","y":2004,"id":"2003/02-1377","sc":1,"sum":"The Court reasoned that \"a straightforward textual analysis\" of the Privacy Act shows that the statute guarantees the $1000 minimum for victims of willful Privacy Act violations only in relation to \"actual damages sustained.\" Individuals subjected to an adverse effect - like the miners in this case - have \"injury enough to open the courthouse door, but without more\" have \"no cause of action for damages under the Privacy Act.\".","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Dun & Bradstreet, Inc. v. Greenmoss Builders, Inc.","cite":"472 U.S. 749","y":1985,"id":"1983/83-18","sc":1,"sum":"Although the trial court correctly perceived that the trial judge's instructions did not satisfy the requirements of Gertz , the Court held that Gertz did not apply since the present case did not involve public speech. Instead the Court looked to apply the logic of Gertz to situations concerning private speech.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Farmer v. Brennan","cite":"511 U.S. 825","y":1994,"id":"1993/92-7247","sc":1,"op":3,"ar":2,"sum":"The Supreme Court held that prison officials may be liable if they showed “deliberate indifference” to a substantial risk of serious harm when the official was subjectively aware of the risk and disregarded it. The Court remanded the case for further consideration of whether prison officials were aware of the risk to Farmer.","sumSrc":"Oyez","by":{"0":"17, 20, 21, 22"}},{"t":"case","label":"Fischl v. General Motors Acceptance Corp.","cite":"708 F.2d 143","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/708/143/","by":{"0":"19"}},{"t":"case","label":"Gertz v. Robert Welch, Inc.","cite":"418 U.S. 323","y":1974,"id":"1973/72-617","sc":1,"sum":"Private individuals need only prove negligence to recover in defamation suits against news media","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Hanger v. Lake County","cite":"390 F.3d 579","y":2004,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/390/579/","by":{"0":"11"}},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"sum":"The Court held that government officials are entitled to qualified immunity but not absolute immunity. Absolute immunity is only available for specific functions that require a total shield from liability.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Harte-Hanks Commc’ns, Inc. v. Connaughton","cite":"491 U.S. 657","y":1989,"id":"1988/88-10","sc":1,"sum":"The Court held that a public figure plaintiff in a libel case must prove that the libelous statement was false or made without any regard for its truth.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Hazen Paper Co. v. Biggins","cite":"507 U.S. 604","y":1993,"id":"1992/91-1600","sc":1,"ar":2,"sum":"The Supreme Court held that interfering with an employee’s pension does not automatically violate the ADEA, though it is a clear ERISA violation. While older employees may have more years of service, age and years of service are independent of each other. On remand, the court of appeals should reconsider whether there is sufficient evidence to support an ADEA violation independent of the pension interference.","sumSrc":"Oyez","by":{"0":"10, 16"}},{"t":"case","label":"Hillstrom v. Best Western TLC Hotel","cite":"354 F.3d 27","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/354/27/","by":{"0":"11"}},{"t":"case","label":"Island Software & Computer Serv., Inc. v. Microsoft Corp.","cite":"413 F.3d 257","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/413/257/","by":{"0":"11"}},{"t":"case","label":"Kolstad v. American Dental Ass’n","cite":"527 U.S. 526","y":1999,"id":"1998/98-208","sc":1,"sum":"In a complicated split opinion, the Court held that if an employee can show their employer knowingly acted in violation of federal law then punitive damages may be sustained. The Court explained that the \"malice\" or \"reckless indifference\" standard applied to the relationship between employers and federal law, and is not a characterization of the severity threshold that the discrimination itself must meet.","sumSrc":"Oyez","by":{"0":"11, 18"}},{"t":"case","label":"McKennon v. Nashville Banner Pub. Co.","cite":"513 U.S. 352","y":1995,"id":"1994/93-1543","sc":1,"sum":"Alleging that her discharge by respondent Nashville Banner Publishing Company violated the Age Discrimination in Employment Act of 1967 (ADEA), petitioner McKennon filed suit seeking a variety of legal and equitable remedies available under the ADEA, including backpay. After she admitted in her deposition that she had copied several of the Banner's confidential documents during her final year of employment, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"McLaughlin v. Richland Shoe Co.","cite":"486 U.S. 128","y":1988,"id":"1987/86-1520","sc":1,"op":1,"ar":1,"sum":"The standard of willfulness adopted in Thurston-thatthe employer either knew or showed reckless disregard as to whether its conduct was prohibited by the FLSA-must be satisfied in order for the 3-year statute of limitations to apply. This standard represents a fair reading of the Act's plain language, since it comports with the general understanding that the word \"willful\" refers to conduct that is \"voluntary,\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 10, 13, 16, 20, 22"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"Murphy v. Waterfront Comm’n","cite":"378 U.S. 52","y":1964,"id":"1963/138","sc":1,"sum":"One jurisdiction in our federal system may not, absent an immunity provision, compel a witness to give testimony which might incriminate him under the laws of another jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Philbin v. Trans Union Corp.","cite":"101 F.3d 957","y":1996,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/101/957/","sum":"Noting “the detrimental effects inaccurate information can visit upon both the individual consumer and the nation’s economy as a whole”.","sumSrc":"brief:0","by":{"0":"28"}},{"t":"case","label":"Porter v. New York Univ. Sch. of Law","cite":"392 F.3d 530","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/392/530/","by":{"0":"11"}},{"t":"case","label":"Professional Real Estate Investors, Inc. v. Columbia Pictures Indus., Inc.","cite":"508 U.S. 49","y":1993,"id":"1992/91-1043","sc":1,"sum":"Although those who petition government for redress are generally immune from antitrust liability, EasternRailroadPresidents Conference v. NoerrMotor Freight,Inc., 365 U. S. 127, such immunity is withheld when petitioning activity \"ostensibly directed toward influencing governmental action, is a mere sham to cover.., an attempt to interfere directly\" with a competitor's business relationships, id., at 144. Petitioner …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Ragin v. Harry Macklowe Real Estate Co.","cite":"6 F.3d 898","y":1993,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/6/898/","by":{"0":"19"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"op":2,"ar":1,"sum":"To give effect to § 5322(a)'s \"willfulness\" requirement, the Government must prove that the defendant acted with knowledge that the structuring he or she undertook was unlawful, not simply that the defendant's purpose was to circumvent a bank's reporting obligation. Section 5324 itself forbids structuring with a \"purpose of evading the [§ 5313(a)] reporting requirements,\" and the lower courts erred in treating the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8"}},{"t":"case","label":"Reeves v. Carlson","cite":"969 P.2d 252","y":1998,"court":"Kan.","url":"https://www.courtlistener.com/c/P.2d/969/252/","by":{"0":"18"}},{"t":"case","label":"RSM, Inc. v. Herbert","cite":"2006 WL 3026344","y":2006,"court":"4th Cir. Oct. 26","by":{"0":"11"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Saba v. Compagnie Nationale Air France","cite":"78 F.3d 664","y":1996,"url":"https://www.courtlistener.com/c/F.3d/78/664/","by":{"0":"22"}},{"t":"case","label":"Screws v. United States","cite":"325 U.S. 91","y":1945,"id":"scdb/1944-039","sc":1,"ar":5,"sum":"1. Upon review of a judgment affirming the conviction, for violation of § 20 of the Criminal Code and conspiracy thereunto, of local law-enforcement officers who arrested a negro citizen for a state offense and wrongfully beat him to death, the judgment is reversed with directions for a new trial. Pp. 92-94, 113. Opinion of DOUGLAS, J., in which the CHIEF JUSTICE, MR. JUSTICE BLAcK and MR. JUSTICE REED concur:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8"}},{"t":"case","label":"Shrader-Miller v. Miller","cite":"855 A.2d 1139","y":2004,"court":"Me.","url":"https://www.courtlistener.com/c/A.2d/855/1139/","by":{"0":"18"}},{"t":"case","label":"Simms v. Royal Thrift & Loan Co.","cite":"2002 WL 32576","y":2002,"court":"Cal. Ct. App. Jan. 11","by":{"0":"17"}},{"t":"case","label":"Smith v. Wade","cite":"461 U.S. 30","y":1983,"id":"1982/81-1196","sc":1,"sum":"Respondent, while an inmate in a Missouri reformatory for youthful first offenders, was harassed, beaten, and sexually assaulted by his cellmates. He brought suit under 42 U. S. C. § 1983 in Federal District Court against petitioner, a guard at the reformatory, and others, alleging that his Eighth Amendment rights had been violated. Because of petitioner's qualified immunity, as a prison guard, from § 1983 …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 17, 23"}},{"t":"case","label":"Spies v. United States","cite":"317 U.S. 492","y":1943,"id":"scdb/1942-089","sc":1,"sum":"Section 145 (b) of the Internal Revenue Code, making it a felony willfully to attempt to evade or defeat a tax, is not violated by willful omissions to make a return and pay a tax, defined in § 145 (a) as misdemeanors. P. 497. 128 F. 2d 743, reversed.. CERTIORARI, post, p. 610, to review the affirmance of a conviction upon an indictment under 26 U. S. C. § 145 (b) for attempting to evade and defeat a federal income …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8"}},{"t":"case","label":"St. Amant v. Thompson","cite":"390 U.S. 727","y":1968,"id":"1967/517","sc":1,"sum":"Justice Byron R. White wrote for an 8-1 majority. First, he reiterated the test established in New York Times v. Sullivan . That test required public officials bringing a defamation lawsuit to show that the statement in question was made with “malice” -- that is, with knowledge that the statement was false or with reckless disregard for whether it was false or not.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Stephens v. South Atl. Canners, Inc.","cite":"848 F.2d 484","y":1988,"url":"https://www.courtlistener.com/c/F.2d/848/484/","by":{"0":"19"}},{"t":"case","label":"Stuart v. United States","cite":"337 F.3d 31","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/337/31/","by":{"0":"19"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"op":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"0":"1, 27"}},{"t":"case","label":"TWA, Inc. v. Thurston","cite":"469 U.S. 111","y":1985,"id":"1984/83-997","sc":1,"op":1,"ar":2,"sum":"The Age Discrimination in Employment Act (ADEA) was amended in 1978 to prohibit the mandatory retirement of a protected employee because of his age. Concerned that its retirement policy, at least as it applied to flight engineers, violated the ADEA, petitioner Trans World Airlines (TWA) adopted a plan permitting any employee in \"flight engineer status\" at age 60 to continue working in that capacity. The plan, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"United States v. Balistrieri","cite":"981 F.2d 916","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/981/916/","by":{"0":"19"}},{"t":"case","label":"United States v. Bishop","cite":"412 U.S. 346","y":1973,"id":"1972/71-1698","sc":1,"sum":"The word \"willfully\" has the same meaning in §§ 7206 (1) and 7207, connoting the voluntary, intentional violation of a known legal duty, and the distinction between the statutes is found in the additional misconduct that is essential to the violation of the felony provision; hence, the District Court properly refused the requested lesserincluded-offense instruction based on respondent's erroneous con-' tention that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8"}},{"t":"case","label":"United States v. Gonsalves","cite":"435 F.3d 64","y":2006,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/435/64/","by":{"0":"19"}},{"t":"case","label":"United States v. Illinois Cent. R.R.","cite":"303 U.S. 239","y":1938,"id":"scdb/1937-111","sc":1,"op":1,"sum":"that the carrier \"knowingly and willfully\" failed to comply with the statute and was subject to the penalty thereby prescribed. P. 242. In statutes denouncing offenses involving turpitude, \"willfully\" is generally used to mean with evil purpose, criminal intent or the like; but in those denouncing acts not in themselves wrong 1' Compare Judicial Code § 211, 36 Stat. 542, 1150, as amended, 38 Stat. 219, 28 U. S. C. § …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 22"}},{"t":"case","label":"United States v. Murdock","cite":"290 U.S. 389","y":1933,"id":"scdb/1933-034","sc":1,"op":1,"sum":"1. In criminal trials in the federal courts, the power of the judge to express an opinion as to the guilt of the defendant, though it 'And see Davis v. New York & N. E. R. Co., 143 Mass. 301, 304; 9 N.E. 815. Needham v. Grand Trunk Ry. Co., 38 Vt. 294, 308-311. Hyde v. Wabash, St. L. & P. Ry. Co., 61 Ia. 441; 16 N.W. 351. Smith v. Condry, 1 How. 28, 33. Slater v. Mexican National R. Co., 194 U.S. 120, 126. Cuba R. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Welch v. Mr. Christmas Inc.","cite":"440 N.E.2d 1317","y":1982,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/440/1317/","by":{"0":"18"}},{"t":"case","label":"Williams Constr. Co. v. Garrison","cite":"400 A.2d 22","y":1979,"court":"Md. Ct. Spec. App.","url":"https://www.courtlistener.com/c/A.2d/400/22/","by":{"0":"18"}},{"t":"case","label":"Williamson v. Handy Button Mach. Co.","cite":"817 F.2d 1290","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/817/1290/","by":{"0":"19"}},{"t":"case","label":"Wilson v. Layne","cite":"526 U.S. 603","y":1999,"id":"1998/98-83","sc":1,"sum":"A \"media ride-along\" in a home violates the Fourth Amendment, but because the state of the law was not clearly established at the time the entry in this case took place, respondent officers are entitled to qualified immunity.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"19"}},{"t":"usc","label":"29 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/29/601","by":{"0":"9, 10, 12, 18"}},{"t":"usc","label":"29 U.S.C. § 626","url":"https://www.law.cornell.edu/uscode/text/29/626","subs":["(b)"],"by":{"0":"10"}},{"t":"usc","label":"42 U.S.C. § 12101","url":"https://www.law.cornell.edu/uscode/text/42/12101","by":{"0":"11, 18"}},{"t":"usc","label":"15 U.S.C. § 1691e","url":"https://www.law.cornell.edu/uscode/text/15/1691e","subs":["(b)"],"by":{"0":"19"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","subs":["(a)","(a)(1)","(a)(2)","(a)(4)","(b)"],"stext":{"head":"§1681. Congressional findings and statement of purpose","paras":[[0,"(a) Accuracy and fairness of credit reporting"],[0,"The Congress makes the following findings:"],[0,"(1) The banking system is dependent upon fair and accurate credit reporting. Inaccurate credit reports directly impair the efficiency of the banking system, and unfair credit reporting methods undermine the public confidence which is essential to the continued functioning of the banking system."],[0,"(2) An elaborate mechanism has been developed for investigating and evaluating the credit worthiness, credit standing, credit capacity, character, and general reputation of consumers."],[0,"(3) Consumer reporting agencies have assumed a vital role in assembling and evaluating consumer credit and other information on consumers."],[0,"(4) There is a need to insure that consumer reporting agencies exercise their grave responsibilities with fairness, impartiality, and a respect for the consumer's right to privacy."],[0,"(b) Reasonable procedures"],[0,"It is the purpose of this subchapter to require that consumer reporting agencies adopt reasonable procedures for meeting the needs of commerce for consumer credit, personnel, insurance, and other information in a manner which is fair and equitable to the consumer, with regard to the confidentiality, accuracy, relevancy, and proper utilization of such information in accordance with the requirements of this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1681. Congressional findings and statement of purpose","tname":"Commerce and Trade","by":{"0":"passim, 2, 2, 20, 1, 2, 20, 2, 20"}},{"t":"usc","label":"15 U.S.C. § 1681a","url":"https://www.law.cornell.edu/uscode/text/15/1681a","subs":["(k)(1)","(k)(1)(B)(i)"],"stext":{"head":"§1681a. Definitions; rules of construction","paras":[[0,"(a) Definitions and rules of construction set forth in this section are applicable for the purposes of this subchapter."],[0,"(b) The term \"person\" means any individual, partnership, corporation, trust, estate, cooperative, association, government or governmental subdivision or agency, or other entity."],[0,"(c) The term \"consumer\" means an individual."],[0,"(d) Consumer Report.—"],[1,"(1) In general.—The term \"consumer report\" means any written, oral, or other communication of any information by a consumer reporting agency bearing on a consumer's credit worthiness, credit standing, credit capacity, character, general reputation, personal characteristics, or mode of living which is used or expected to be used or collected in whole or in part for the purpose of serving as a factor in establishing the consumer's eligibility for—"],[2,"(A) credit or insurance to be used primarily for personal, family, or household purposes;"],[2,"(B) employment purposes; or"],[2,"(C) any other purpose authorized under section 1681b of this title."],[1,"(2) Exclusions.—Except as provided in paragraph (3), the term \"consumer report\" does not include—"],[2,"(A) subject to section 1681s–3 of this title, any—"],[3,"(i) report containing information solely as to transactions or experiences between the consumer and the person making the report;"],[3,"(ii) communication of that information among persons related by common ownership or affiliated by corporate control; or"],[3,"(iii) communication of other information among persons related by common ownership or affiliated by corporate control, if it is clearly and conspicuously disclosed to the consumer that the information may be communicated among such persons and the consumer is given the opportunity, before the time that the information is initially communicated, to direct that such information not be communicated among such persons;"],[2,"(B) any authorization or approval of a specific extension of credit directly or indirectly by the issuer of a credit card or similar device;"],[2,"(C) any report in which a person who has been requested by a third party to make a specific extension of credit directly or indirectly to a consumer conveys his or her decision with respect to such request, if the third party advises the consumer of the name and address of the person to whom the request was made, and such person makes the disclosures to the consumer required under section 1681m of this title; or"],[2,"(D) a communication described in subsection (o) or (x).1"],[1,"(3) Restriction on sharing of medical information.—Except for information or any communication of information disclosed as provided in section 1681b(g)(3) of this title, the exclusions in paragraph (2) shall not apply with respect to information disclosed to any person related by common ownership or affiliated by corporate control, if the information is—"],[2,"(A) medical information;"],[2,"(B) an individualized list or description based on the payment transactions of the consumer for medical products or services; or"],[2,"(C) an aggregate list of identified consumers based on payment transactions for medical products or services."],[0,"(e) The term \"investigative consumer report\" means a consumer report or portion thereof in which information on a consumer's character, general reputation, personal characteristics, or mode of living is obtained through personal interviews with neighbors, friends, or associates of the consumer reported on or with others with whom he is acquainted or who may have knowledge concerning any such items of information. However, such information shall not include specific factual information on a consumer's credit record obtained directly from a creditor of the consumer or from a consumer reporting agency when such information was obtained directly from a creditor of the consumer or from the consumer."],[0,"(f) The term \"consumer reporting agency\" means any person which, for monetary fees, dues, or on a cooperative nonprofit basis, regularly engages in whole or in part in the practice of assembling or evaluating consumer credit information or other information on consumers for the purpose of furnishing consumer reports to third parties, and which uses any means or facility of interstate commerce for the purpose of preparing or furnishing consumer reports."],[0,"(g) The term \"file\", when used in connection with information on any consumer, means all of the information on that consumer recorded and retained by a consumer reporting agency regardless of how the information is stored."],[0,"(h) The term \"employment purposes\" when used in connection with a consumer report means a report used for the purpose of evaluating a consumer for employment, promotion, reassignment or retention as an employee."],[0,"(i) Medical Information.—The term \"medical information\"—"],[1,"(1) means information or data, whether oral or recorded, in any form or medium, created by or derived from a health care provider or the consumer, that relates to—"],[2,"(A) the past, present, or future physical, mental, or behavioral health or condition of an individual;"],[2,"(B) the provision of health care to an individual; or"],[2,"(C) the payment for the provision of health care to an individual.2"],[1,"(2) does not include the age or gender of a consumer, demographic information about the consumer, including a consumer's residence address or e-mail address, or any other information about a consumer that does not relate to the physical, mental, or behavioral health or condition of a consumer, including the existence or value of any insurance policy."],[0,"(j) Definitions Relating to Child Support Obligations.—"],[1,"(1) Overdue support.—The term \"overdue support\" has the meaning given to such term in section 666(e) of title 42."],[1,"(2) State or local child support enforcement agency.—The term \"State or local child support enforcement agency\" means a State or local agency which administers a State or local program for establishing and enforcing child support obligations."],[0,"(k) Adverse Action.—"],[1,"(1) Actions included.—The term \"adverse action\"—"],[2,"(A) has the same meaning as in section 1691(d)(6) of this title; and"],[2,"(B) means—"],[3,"(i) a denial or cancellation of, an increase in any charge for, or a reduction or other adverse or unfavorable change in the terms of coverage or amount of, any insurance, existing or applied for, in connection with the underwriting of insurance;"],[3,"(ii) a denial of employment or any other decision for employment purposes that adversely affects any current or prospective employee;"],[3,"(iii) a denial or cancellation of, an increase in any charge for, or any other adverse or unfavorable change in the terms of, any license or benefit described in section 1681b(a)(3)(D) of this title; and"],[3,"(iv) an action taken or determination that is—"],[4,"(I) made in connection with an application that was made by, or a transaction that was initiated by, any consumer, or in connection with a review of an account under section 1681b(a)(3)(F)(ii) of this title; and"],[4,"(II) adverse to the interests of the consumer."],[1,"(2) Applicable findings, decisions, commentary, and orders.—For purposes of any determination of whether an action is an adverse action under paragraph (1)(A), all appropriate final findings, decisions, commentary, and orders issued under section 1691(d)(6) of this title by the Bureau or any court shall apply."],[0,"(l) Firm Offer of Credit or Insurance.—The term \"firm offer of credit or insurance\" means any offer of credit or insurance to a consumer that will be honored if the consumer is determined, based on information in a consumer report on the consumer, to meet the specific criteria used to select the consumer for the offer, except that the offer may be further conditioned on one or more of the following:"],[1,"(1) The consumer being determined, based on information in the consumer's application for the credit or insurance, to meet specific criteria bearing on credit worthiness or insurability, as applicable, that are established—"],[2,"(A) before selection of the consumer for the offer; and"],[2,"(B) for the purpose of determining whether to extend credit or insurance pursuant to the offer."],[1,"(2) Verification—"],[2,"(A) that the consumer continues to meet the specific criteria used to select the consumer for the offer, by using information in a consumer report on the consumer, information in the consumer's application for the credit or insurance, or other information bearing on the credit worthiness or insurability of the consumer; or"],[2,"(B) of the information in the consumer's application for the credit or insurance, to determine that the consumer meets the specific criteria bearing on credit worthiness or insurability."],[1,"(3) The consumer furnishing any collateral that is a requirement for the extension of the credit or insurance that was—"],[2,"(A) established before selection of the consumer for the offer of credit or insurance; and"],[2,"(B) disclosed to the consumer in the offer of credit or insurance."],[0,"(m) Credit or Insurance Transaction That Is Not Initiated by the Consumer.—The term \"credit or insurance transaction that is not initiated by the consumer\" does not include the use of a consumer report by a person with which the consumer has an account or insurance policy, for purposes of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681a?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§1681a. Definitions; rules of construction","tname":"Commerce and Trade","by":{"0":"25, 5, 7, 25, 27"}},{"t":"usc","label":"15 U.S.C. § 1681b","url":"https://www.law.cornell.edu/uscode/text/15/1681b","subs":["(a)","(a)(3)(A)","(f)"],"by":{"0":"26, 2, 13, 14"}},{"t":"usc","label":"15 U.S.C. § 1681g","url":"https://www.law.cornell.edu/uscode/text/15/1681g","stext":{"head":"§1681g. Disclosures to consumers","paras":[[0,"(a) Information on file; sources; report recipients"],[0,"Every consumer reporting agency shall, upon request, and subject to section 1681h(a)(1) of this title, clearly and accurately disclose to the consumer:"],[0,"(1) All information in the consumer's file at the time of the request, except that—"],[1,"(A) if the consumer to whom the file relates requests that the first 5 digits of the social security number (or similar identification number) of the consumer not be included in the disclosure and the consumer reporting agency has received appropriate proof of the identity of the requester, the consumer reporting agency shall so truncate such number in such disclosure; and"],[1,"(B) nothing in this paragraph shall be construed to require a consumer reporting agency to disclose to a consumer any information concerning credit scores or any other risk scores or predictors relating to the consumer."],[0,"(2) The sources of the information; except that the sources of information acquired solely for use in preparing an investigative consumer report and actually used for no other purpose need not be disclosed: Provided, That in the event an action is brought under this subchapter, such sources shall be available to the plaintiff under appropriate discovery procedures in the court in which the action is brought."],[0,"(3)(A) Identification of each person (including each end-user identified under section 1681e(e)(1) of this title) that procured a consumer report—"],[1,"(i) for employment purposes, during the 2-year period preceding the date on which the request is made; or"],[1,"(ii) for any other purpose, during the 1-year period preceding the date on which the request is made."],[0,"(B) An identification of a person under subparagraph (A) shall include—"],[1,"(i) the name of the person or, if applicable, the trade name (written in full) under which such person conducts business; and"],[1,"(ii) upon request of the consumer, the address and telephone number of the person."],[0,"(C) Subparagraph (A) does not apply if—"],[1,"(i) the end user is an agency or department of the United States Government that procures the report from the person for purposes of determining the eligibility of the consumer to whom the report relates to receive access or continued access to classified information (as defined in section 1681b(b)(4)(E)(i) 1 of this title); and"],[1,"(ii) the head of the agency or department makes a written finding as prescribed under section 1681b(b)(4)(A) of this title."],[0,"(4) The dates, original payees, and amounts of any checks upon which is based any adverse characterization of the consumer, included in the file at the time of the disclosure."],[0,"(5) A record of all inquiries received by the agency during the 1-year period preceding the request that identified the consumer in connection with a credit or insurance transaction that was not initiated by the consumer."],[0,"(6) If the consumer requests the credit file and not the credit score, a statement that the consumer may request and obtain a credit score."],[0,"(b) Exempt information"],[0,"The requirements of subsection (a) respecting the disclosure of sources of information and the recipients of consumer reports do not apply to information received or consumer reports furnished prior to the effective date of this subchapter except to the extent that the matter involved is contained in the files of the consumer reporting agency on that date."],[0,"(c) Summary of rights to obtain and dispute information in consumer reports and to obtain credit scores"],[0,"(1) Commission 2 summary of rights required"],[0,"(A) In general"],[2,"The Commission 2 shall prepare a model summary of the rights of consumers under this subchapter."],[0,"(B) Content of summary"],[2,"The summary of rights prepared under subparagraph (A) shall include a description of—"],[3,"(i) the right of a consumer to obtain a copy of a consumer report under subsection (a) from each consumer reporting agency;"],[3,"(ii) the frequency and circumstances under which a consumer is entitled to receive a consumer report without charge under section 1681j of this title;"],[3,"(iii) the right of a consumer to dispute information in the file of the consumer under section 1681i of this title;"],[3,"(iv) the right of a consumer to obtain a credit score from a consumer reporting agency, and a description of how to obtain a credit score;"],[3,"(v) the method by which a consumer can contact, and obtain a consumer report from, a consumer reporting agency without charge, as provided in the regulations of the Bureau prescribed under section 211(c) 1 of the Fair and Accurate Credit Transactions Act of 2003; and"],[3,"(vi) the method by which a consumer can contact, and obtain a consumer report from, a consumer reporting agency described in section 1681a(w) 1 of this title, as provided in the regulations of the Bureau prescribed under section 1681j(a)(1)(C) of this title."],[0,"(C) Availability of summary of rights"],[2,"The Commission 2 shall—"],[3,"(i) actively publicize the availability of the summary of rights prepared under this paragraph;"],[3,"(ii) conspicuously post on its Internet website the availability of such summary of rights; and"],[3,"(iii) promptly make such summary of rights available to consumers, on request."],[0,"(2) Summary of rights required to be included with agency disclosures"],[1,"A consumer reporting agency shall provide to a consumer, with each written disclosure by the agency to the consumer under this section—"],[2,"(A) the summary of rights prepared by the Bureau under paragraph (1);"],[2,"(B) in the case of a consumer reporting agency described in section 1681a(p) of this title, a toll-free telephone number established by the agency, at which personnel are accessible to consumers during normal business hours;"],[2,"(C) a list of all Federal agencies responsible for enforcing any provision of this subchapter, and the address and any appropriate phone number of each such agency, in a form that will assist the consumer in selecting the appropriate agency;"],[2,"(D) a statement that the consumer may have additional rights under State law, and that the consumer may wish to contact a State or local consumer protection agency or a State attorney general (or the equivalent thereof) to learn of those rights; and"],[2,"(E) a statement that a consumer reporting agency is not required to remove accurate derogatory information from the file of a consumer, unless the information is outdated under section 1681c of this title or cannot be verified."],[0,"(d) Summary of rights of identity theft victims"],[0,"(1) In general"],[1,"The Commission,2 in consultation with the Federal banking agencies and the National Credit Union Administration, shall prepare a model summary of the rights of consumers under this subchapter with respect to the procedures for remedying the effects of fraud or identity theft involving credit, an electronic fund transfer, or an account or transaction at or with a financial institution or other creditor."],[0,"(2) Summary of rights and contact information"],[1,"Beginning 60 days after the date on which the model summary of rights is prescribed in final form by the Bureau pursuant to paragraph (1), if any consumer contacts a consumer reporting agency and expresses a belief that the consumer is a victim of fraud or identity theft involving credit, an electronic fund transfer, or an account or transaction at or with a financial institution or other creditor, the consumer reporting agency shall, in addition to any other action that the agency may take, provide the consumer with a summary of rights that contains all of the information required by the Bureau under paragraph (1), and information on how to contact the Bureau to obtain more detailed information."],[0,"(e) Information available to victims"],[0,"(1) In general"],[1,"For the purpose of documenting fraudulent transactions resulting from identity theft, not later than 30 days after the date of receipt of a request from a victim in accordance with paragraph (3), and subject to verification of the identity of the victim and the claim of identity theft in accordance with paragraph (2), a business entity that has provided credit to, provided for consideration products, goods, or services to, accepted payment from, or otherwise entered into a commercial transaction for consideration with, a person who has allegedly made unauthorized use of the means of identification of the victim, shall provide a copy of application and business transaction records in the control of the business entity, whether maintained by the business entity or by another person on behalf of the business entity, evidencing any transaction alleged to be a result of identity theft to—"],[2,"(A) the victim;"],[2,"(B) any Federal, State, or local government law enforcement agency or officer specified by the victim in such a request; or"],[2,"(C) any law enforcement agency investigating the identity theft and authorized by the victim to take receipt of records provided under this subsection."],[0,"(2) Verification of identity and claim"],[1,"Before a business entity provides any information under paragraph (1), unless the business entity, at its discretion, otherwise has a high degree of confidence that it knows the identity of the victim making a request under paragraph (1), the victim shall provide to the business entity—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681g?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1681g. Disclosures to consumers","tname":"Commerce and Trade","by":{"0":"2"}},{"t":"usc","label":"15 U.S.C. § 1681i","url":"https://www.law.cornell.edu/uscode/text/15/1681i","by":{"0":"2"}},{"t":"usc","label":"15 U.S.C. § 1681m","url":"https://www.law.cornell.edu/uscode/text/15/1681m","subs":["(a)","(h)(8)"],"stext":{"head":"§1681m. Requirements on users of consumer reports","paras":[[0,"(a) Duties of users taking adverse actions on basis of information contained in consumer reports"],[0,"If any person takes any adverse action with respect to any consumer that is based in whole or in part on any information contained in a consumer report, the person shall—"],[1,"(1) provide oral, written, or electronic notice of the adverse action to the consumer;"],[1,"(2) provide to the consumer written or electronic disclosure—"],[2,"(A) of a numerical credit score as defined in section 1681g(f)(2)(A) of this title used by such person in taking any adverse action based in whole or in part on any information in a consumer report; and"],[2,"(B) of the information set forth in subparagraphs (B) through (E) of section 1681g(f)(1) of this title;"],[1,"(3) provide to the consumer orally, in writing, or electronically—"],[2,"(A) the name, address, and telephone number of the consumer reporting agency (including a toll-free telephone number established by the agency if the agency compiles and maintains files on consumers on a nationwide basis) that furnished the report to the person; and"],[2,"(B) a statement that the consumer reporting agency did not make the decision to take the adverse action and is unable to provide the consumer the specific reasons why the adverse action was taken; and"],[1,"(4) provide to the consumer an oral, written, or electronic notice of the consumer's right—"],[2,"(A) to obtain, under section 1681j of this title, a free copy of a consumer report on the consumer from the consumer reporting agency referred to in paragraph (3), which notice shall include an indication of the 60-day period under that section for obtaining such a copy; and"],[2,"(B) to dispute, under section 1681i of this title, with a consumer reporting agency the accuracy or completeness of any information in a consumer report furnished by the agency."],[0,"(b) Adverse action based on information obtained from third parties other than consumer reporting agencies"],[0,"(1) In general"],[1,"Whenever credit for personal, family, or household purposes involving a consumer is denied or the charge for such credit is increased either wholly or partly because of information obtained from a person other than a consumer reporting agency bearing upon the consumer's credit worthiness, credit standing, credit capacity, character, general reputation, personal characteristics, or mode of living, the user of such information shall, within a reasonable period of time, upon the consumer's written request for the reasons for such adverse action received within sixty days after learning of such adverse action, disclose the nature of the information to the consumer. The user of such information shall clearly and accurately disclose to the consumer his right to make such written request at the time such adverse action is communicated to the consumer."],[0,"(2) Duties of person taking certain actions based on information provided by affiliate"],[0,"(A) Duties, generally"],[2,"If a person takes an action described in subparagraph (B) with respect to a consumer, based in whole or in part on information described in subparagraph (C), the person shall—"],[3,"(i) notify the consumer of the action, including a statement that the consumer may obtain the information in accordance with clause (ii); and"],[3,"(ii) upon a written request from the consumer received within 60 days after transmittal of the notice required by clause (i), disclose to the consumer the nature of the information upon which the action is based by not later than 30 days after receipt of the request."],[0,"(B) Action described"],[2,"An action referred to in subparagraph (A) is an adverse action described in section 1681a(k)(1)(A) of this title, taken in connection with a transaction initiated by the consumer, or any adverse action described in clause (i) or (ii) of section 1681a(k)(1)(B) of this title."],[0,"(C) Information described"],[2,"Information referred to in subparagraph (A)—"],[3,"(i) except as provided in clause (ii), is information that—"],[4,"(I) is furnished to the person taking the action by a person related by common ownership or affiliated by common corporate control to the person taking the action; and"],[4,"(II) bears on the credit worthiness, credit standing, credit capacity, character, general reputation, personal characteristics, or mode of living of the consumer; and"],[3,"(ii) does not include—"],[4,"(I) information solely as to transactions or experiences between the consumer and the person furnishing the information; or"],[4,"(II) information in a consumer report."],[0,"(c) Reasonable procedures to assure compliance"],[0,"No person shall be held liable for any violation of this section if he shows by a preponderance of the evidence that at the time of the alleged violation he maintained reasonable procedures to assure compliance with the provisions of this section."],[0,"(d) Duties of users making written credit or insurance solicitations on basis of information contained in consumer files"],[0,"(1) In general"],[1,"Any person who uses a consumer report on any consumer in connection with any credit or insurance transaction that is not initiated by the consumer, that is provided to that person under section 1681b(c)(1)(B) of this title, shall provide with each written solicitation made to the consumer regarding the transaction a clear and conspicuous statement that—"],[2,"(A) information contained in the consumer's consumer report was used in connection with the transaction;"],[2,"(B) the consumer received the offer of credit or insurance because the consumer satisfied the criteria for credit worthiness or insurability under which the consumer was selected for the offer;"],[2,"(C) if applicable, the credit or insurance may not be extended if, after the consumer responds to the offer, the consumer does not meet the criteria used to select the consumer for the offer or any applicable criteria bearing on credit worthiness or insurability or does not furnish any required collateral;"],[2,"(D) the consumer has a right to prohibit information contained in the consumer's file with any consumer reporting agency from being used in connection with any credit or insurance transaction that is not initiated by the consumer; and"],[2,"(E) the consumer may exercise the right referred to in subparagraph (D) by notifying a notification system established under section 1681b(e) of this title."],[0,"(2) Disclosure of address and telephone number; format"],[1,"A statement under paragraph (1) shall—"],[2,"(A) include the address and toll-free telephone number of the appropriate notification system established under section 1681b(e) of this title; and"],[2,"(B) be presented in such format and in such type size and manner as to be simple and easy to understand, as established by the Bureau, by rule, in consultation with the Federal Trade Commission, the Federal banking agencies, and the National Credit Union Administration."],[0,"(3) Maintaining criteria on file"],[1,"A person who makes an offer of credit or insurance to a consumer under a credit or insurance transaction described in paragraph (1) shall maintain on file the criteria used to select the consumer to receive the offer, all criteria bearing on credit worthiness or insurability, as applicable, that are the basis for determining whether or not to extend credit or insurance pursuant to the offer, and any requirement for the furnishing of collateral as a condition of the extension of credit or insurance, until the expiration of the 3-year period beginning on the date on which the offer is made to the consumer."],[0,"(4) Authority of Federal agencies regarding unfair or deceptive acts or practices not affected"],[1,"This section is not intended to affect the authority of any Federal or State agency to enforce a prohibition against unfair or deceptive acts or practices, including the making of false or misleading statements in connection with a credit or insurance transaction that is not initiated by the consumer."],[0,"(e) Red flag guidelines and regulations required"],[0,"(1) Guidelines"],[1,"The Federal banking agencies, the National Credit Union Administration, the Federal Trade Commission, the Commodity Futures Trading Commission, and the Securities and Exchange Commission shall jointly, with respect to the entities that are subject to their respective enforcement authority under section 1681s of this title—"],[2,"(A) establish and maintain guidelines for use by each financial institution and each creditor regarding identity theft with respect to account holders at, or customers of, such entities, and update such guidelines as often as necessary;"],[2,"(B) prescribe regulations requiring each financial institution and each creditor to establish reasonable policies and procedures for implementing the guidelines established pursuant to subparagraph (A), to identify possible risks to account holders or customers or to the safety and soundness of the institution or customers; and"],[2,"(C) prescribe regulations applicable to card issuers to ensure that, if a card issuer receives notification of a change of address for an existing account, and within a short period of time (during at least the first 30 days after such notification is received) receives a request for an additional or replacement card for the same account, the card issuer may not issue the additional or replacement card, unless the card issuer, in accordance with reasonable policies and procedures—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681m?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1681m. Requirements on users of consumer reports","tname":"Commerce and Trade","by":{"0":"3, 2, 27, 1, 3"}},{"t":"usc","label":"15 U.S.C. § 1681n","url":"https://www.law.cornell.edu/uscode/text/15/1681n","subs":["(a)","(a)(1)(A)","(a)(1)(B)","(b)"],"stext":{"head":"§1681n. Civil liability for willful noncompliance","paras":[[0,"(a) In general"],[0,"Any person who willfully fails to comply with any requirement imposed under this subchapter with respect to any consumer is liable to that consumer in an amount equal to the sum of—"],[1,"(1)(A) any actual damages sustained by the consumer as a result of the failure or damages of not less than $100 and not more than $1,000; or"],[1,"(B) in the case of liability of a natural person for obtaining a consumer report under false pretenses or knowingly without a permissible purpose, actual damages sustained by the consumer as a result of the failure or $1,000, whichever is greater;"],[1,"(2) such amount of punitive damages as the court may allow; and"],[1,"(3) in the case of any successful action to enforce any liability under this section, the costs of the action together with reasonable attorney's fees as determined by the court."],[0,"(b) Civil liability for knowing noncompliance"],[0,"Any person who obtains a consumer report from a consumer reporting agency under false pretenses or knowingly without a permissible purpose shall be liable to the consumer reporting agency for actual damages sustained by the consumer reporting agency or $1,000, whichever is greater."],[0,"(c) Attorney's fees"],[0,"Upon a finding by the court that an unsuccessful pleading, motion, or other paper filed in connection with an action under this section was filed in bad faith or for purposes of harassment, the court shall award to the prevailing party attorney's fees reasonable in relation to the work expended in responding to the pleading, motion, or other paper."],[0,"(d) Clarification of willful noncompliance"],[0,"For the purposes of this section, any person who printed an expiration date on any receipt provided to a consumer cardholder at a point of sale or transaction between December 4, 2004, and June 3, 2008, but otherwise complied with the requirements of section 1681c(g) of this title for such receipt shall not be in willful noncompliance with section 1681c(g) of this title by reason of printing such expiration date on the receipt."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681n?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":2,"head":"§1681n. Civil liability for willful noncompliance","tname":"Commerce and Trade","by":{"0":"14, 15, 10, 13, 14, 3, 3, 13, 13, 14"}},{"t":"usc","label":"15 U.S.C. § 1681o","url":"https://www.law.cornell.edu/uscode/text/15/1681o","subs":["(a)"],"stext":{"head":"§1681o. Civil liability for negligent noncompliance","paras":[[0,"(a) In general"],[0,"Any person who is negligent in failing to comply with any requirement imposed under this subchapter with respect to any consumer is liable to that consumer in an amount equal to the sum of—"],[1,"(1) any actual damages sustained by the consumer as a result of the failure; and"],[1,"(2) in the case of any successful action to enforce any liability under this section, the costs of the action together with reasonable attorney's fees as determined by the court."],[0,"(b) Attorney's fees"],[0,"On a finding by the court that an unsuccessful pleading, motion, or other paper filed in connection with an action under this section was filed in bad faith or for purposes of harassment, the court shall award to the prevailing party attorney's fees reasonable in relation to the work expended in responding to the pleading, motion, or other paper."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681o?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1681o. Civil liability for negligent noncompliance","tname":"Commerce and Trade","by":{"0":"3, 15, 16, 3"}},{"t":"usc","label":"15 U.S.C. § 1681p","url":"https://www.law.cornell.edu/uscode/text/15/1681p","by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 1681q","url":"https://www.law.cornell.edu/uscode/text/15/1681q","stext":{"head":"§1681q. Obtaining information under false pretenses","paras":[[0,"Any person who knowingly and willfully obtains information on a consumer from a consumer reporting agency under false pretenses shall be fined under title 18, imprisoned for not more than 2 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681q?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1681q. Obtaining information under false pretenses","tname":"Commerce and Trade","by":{"0":"14"}},{"t":"usc","label":"15 U.S.C. § 1681r","url":"https://www.law.cornell.edu/uscode/text/15/1681r","by":{"0":"14"}},{"t":"usc","label":"15 U.S.C. § 1681s","url":"https://www.law.cornell.edu/uscode/text/15/1681s","subs":["(a)","(a)(2)(A)"],"stext":{"head":"§1681s. Administrative enforcement","paras":[[0,"(a) Enforcement by Federal Trade Commission"],[0,"(1) In general"],[1,"The Federal Trade Commission shall be authorized to enforce compliance with the requirements imposed by this subchapter under the Federal Trade Commission Act (15 U.S.C. 41 et seq.), with respect to consumer reporting agencies and all other persons subject thereto, except to the extent that enforcement of the requirements imposed under this subchapter is specifically committed to some other Government agency under any of subparagraphs (A) through (G) of subsection (b)(1), and subject to subtitle B of the Consumer Financial Protection Act of 2010 [12 U.S.C. 5511 et seq.], subsection (b).1 For the purpose of the exercise by the Federal Trade Commission of its functions and powers under the Federal Trade Commission Act, a violation of any requirement or prohibition imposed under this subchapter shall constitute an unfair or deceptive act or practice in commerce, in violation of section 5(a) of the Federal Trade Commission Act (15 U.S.C. 45(a)), and shall be subject to enforcement by the Federal Trade Commission under section 5(b) of that Act [15 U.S.C. 45(b)] with respect to any consumer reporting agency or person that is subject to enforcement by the Federal Trade Commission pursuant to this subsection, irrespective of whether that person is engaged in commerce or meets any other jurisdictional tests under the Federal Trade Commission Act. The Federal Trade Commission shall have such procedural, investigative, and enforcement powers, including the power to issue procedural rules in enforcing compliance with the requirements imposed under this subchapter and to require the filing of reports, the production of documents, and the appearance of witnesses, as though the applicable terms and conditions of the Federal Trade Commission Act were part of this subchapter. Any person violating any of the provisions of this subchapter shall be subject to the penalties and entitled to the privileges and immunities provided in the Federal Trade Commission Act as though the applicable terms and provisions of such Act are part of this subchapter."],[0,"(2) Penalties"],[0,"(A) Knowing violations"],[2,"Except as otherwise provided by subtitle B of the Consumer Financial Protection Act of 2010, in the event of a knowing violation, which constitutes a pattern or practice of violations of this subchapter, the Federal Trade Commission may commence a civil action to recover a civil penalty in a district court of the United States against any person that violates this subchapter. In such action, such person shall be liable for a civil penalty of not more than $2,500 per violation."],[0,"(B) Determining penalty amount"],[2,"In determining the amount of a civil penalty under subparagraph (A), the court shall take into account the degree of culpability, any history of such prior conduct, ability to pay, effect on ability to continue to do business, and such other matters as justice may require."],[0,"(C) Limitation"],[2,"Notwithstanding paragraph (2), a court may not impose any civil penalty on a person for a violation of section 1681s–2(a)(1) of this title, unless the person has been enjoined from committing the violation, or ordered not to commit the violation, in an action or proceeding brought by or on behalf of the Federal Trade Commission, and has violated the injunction or order, and the court may not impose any civil penalty for any violation occurring before the date of the violation of the injunction or order."],[0,"(b) Enforcement by other agencies"],[0,"(1) In general"],[1,"Subject to subtitle B of the Consumer Financial Protection Act of 2010, compliance with the requirements imposed under this subchapter with respect to consumer reporting agencies, persons who use consumer reports from such agencies, persons who furnish information to such agencies, and users of information that are subject to section 1681m(d) of this title shall be enforced under—"],[2,"(A) section 8 of the Federal Deposit Insurance Act (12 U.S.C. 1818), by the appropriate Federal banking agency, as defined in section 3(q) of the Federal Deposit Insurance Act (12 U.S.C. 1813(q)), with respect to—"],[3,"(i) any national bank or State savings association, and any Federal branch or Federal agency of a foreign bank;"],[3,"(ii) any member bank of the Federal Reserve System (other than a national bank), a branch or agency of a foreign bank (other than a Federal branch, Federal agency, or insured State branch of a foreign bank), a commercial lending company owned or controlled by a foreign bank, and any organization operating under section 25 or 25A of the Federal Reserve Act [12 U.S.C. 601 et seq., 611 et seq.]; and"],[3,"(iii) any bank or Federal savings association insured by the Federal Deposit Insurance Corporation (other than a member of the Federal Reserve System) and any insured State branch of a foreign bank;"],[2,"(B) the Federal Credit Union Act (12 U.S.C. 1751 et seq.), by the Administrator of the National Credit Union Administration with respect to any Federal credit union;"],[2,"(C) subtitle IV of title 49, by the Secretary of Transportation, with respect to all carriers subject to the jurisdiction of the Surface Transportation Board;"],[2,"(D) part A of subtitle VII of title 49, by the Secretary of Transportation, with respect to any air carrier or foreign air carrier subject to that part;"],[2,"(E) the Packers and Stockyards Act, 1921 (7 U.S.C. 181 et seq.) (except as provided in section 406 of that Act [7 U.S.C. 226, 227]), by the Secretary of Agriculture, with respect to any activities subject to that Act;"],[2,"(F) the Commodity Exchange Act [7 U.S.C. 1 et seq.], with respect to a person subject to the jurisdiction of the Commodity Futures Trading Commission;"],[2,"(G) the Federal securities laws, and any other laws that are subject to the jurisdiction of the Securities and Exchange Commission, with respect to a person that is subject to the jurisdiction of the Securities and Exchange Commission; and"],[2,"(H) subtitle E of the Consumer Financial Protection Act of 2010 [12 U.S.C. 5561 et seq.], by the Bureau, with respect to any person subject to this subchapter."],[0,"(2) Incorporated definitions"],[1,"The terms used in paragraph (1) that are not defined in this subchapter or otherwise defined in section 3(s) of the Federal Deposit Insurance Act (12 U.S.C. 1813(s)) have the same meanings as in section 1(b) of the International Banking Act of 1978 (12 U.S.C. 3101)."],[0,"(c) State action for violations"],[0,"(1) Authority of States"],[1,"In addition to such other remedies as are provided under State law, if the chief law enforcement officer of a State, or an official or agency designated by a State, has reason to believe that any person has violated or is violating this subchapter, the State—"],[2,"(A) may bring an action to enjoin such violation in any appropriate United States district court or in any other court of competent jurisdiction;"],[2,"(B) subject to paragraph (5), may bring an action on behalf of the residents of the State to recover—"],[3,"(i) damages for which the person is liable to such residents under sections 1681n and 1681o of this title as a result of the violation;"],[3,"(ii) in the case of a violation described in any of paragraphs (1) through (3) of section 1681s–2(c) of this title, damages for which the person would, but for section 1681s–2(c) of this title, be liable to such residents as a result of the violation; or"],[3,"(iii) damages of not more than $1,000 for each willful or negligent violation; and"],[2,"(C) in the case of any successful action under subparagraph (A) or (B), shall be awarded the costs of the action and reasonable attorney fees as determined by the court."],[0,"(2) Rights of Federal regulators"],[1,"The State shall serve prior written notice of any action under paragraph (1) upon the Bureau and the Federal Trade Commission or the appropriate Federal regulator determined under subsection (b) and provide the Bureau and the Federal Trade Commission or appropriate Federal regulator with a copy of its complaint, except in any case in which such prior notice is not feasible, in which case the State shall serve such notice immediately upon instituting such action. The Bureau and the Federal Trade Commission or appropriate Federal regulator shall have the right—"],[2,"(A) to intervene in the action;"],[2,"(B) upon so intervening, to be heard on all matters arising therein;"],[2,"(C) to remove the action to the appropriate United States district court; and"],[2,"(D) to file petitions for appeal."],[0,"(3) Investigatory powers"],[1,"For purposes of bringing any action under this subsection, nothing in this subsection shall prevent the chief law enforcement officer, or an official or agency designated by a State, from exercising the powers conferred on the chief law enforcement officer or such official by the laws of such State to conduct investigations or to administer oaths or affirmations or to compel the attendance of witnesses or the production of documentary and other evidence."],[0,"(4) Limitation on State action while Federal action pending"],[1,"If the Bureau, the Federal Trade Commission, or the appropriate Federal regulator has instituted a civil action or an administrative action under section 8 of the Federal Deposit Insurance Act [12 U.S.C. 1818] for a violation of this subchapter, no State may, during the pendency of such action, bring an action under this section against any defendant named in the complaint of the Bureau, the Federal Trade Commission, or the appropriate Federal regulator for any violation of this subchapter that is alleged in that complaint."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681s?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1681s. Administrative enforcement","tname":"Commerce and Trade","by":{"0":"1, 14"}},{"t":"usc","label":"42 U.S.C. § 3601","url":"https://www.law.cornell.edu/uscode/text/42/3601","by":{"0":"19"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"0":"10, 12"}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","subs":["(e)"],"by":{"0":"10"}},{"t":"usc","label":"29 U.S.C. § 255","url":"https://www.law.cornell.edu/uscode/text/29/255","subs":["(a)"],"by":{"0":"10"}},{"t":"law","label":"Pub. L. No. 89-601","url":"https://www.govinfo.gov/link/statute/80/844","by":{"0":"12"}},{"t":"usc","label":"29 U.S.C. § 2617","url":"https://www.law.cornell.edu/uscode/text/29/2617","by":{"0":"11"}},{"t":"usc","label":"29 U.S.C. § 666","url":"https://www.law.cornell.edu/uscode/text/29/666","subs":["(a)"],"by":{"0":"11"}},{"t":"usc","label":"11 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/11/523","subs":["(a)(6)"],"by":{"0":"11"}},{"t":"usc","label":"17 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/17/504","subs":["(c)(2)"],"by":{"0":"11"}},{"t":"usc","label":"18 U.S.C. § 923","url":"https://www.law.cornell.edu/uscode/text/18/923","subs":["(e)"],"by":{"0":"11"}},{"t":"usc","label":"38 U.S.C. § 1110","url":"https://www.law.cornell.edu/uscode/text/38/1110","by":{"0":"11"}},{"t":"usc","label":"42 U.S.C. § 1981","url":"https://www.law.cornell.edu/uscode/text/42/1981","by":{"0":"19"}},{"t":"usc","label":"42 U.S.C. § 1981a","url":"https://www.law.cornell.edu/uscode/text/42/1981a","subs":["(b)(1)"],"by":{"0":"18, 11"}},{"t":"usc","label":"42 U.S.C. § 1982","url":"https://www.law.cornell.edu/uscode/text/42/1982","by":{"0":"19"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"0":"12"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","by":{"0":"11"}},{"t":"reg","label":"16 C.F.R. pt. 600","url":"https://www.ecfr.gov/current/title-16/part-600","by":{"0":"1, 25"}}]};